public class Ex03FinallyReturn {
    static int tricky() {
        try {
            return 1;
        } finally {
            return 2;
        }
    }
    static int withValue() {
        int x = 10;
        try {
            return x;
        } finally {
            x = 20;
        }
    }
    public static void main(String[] args) {
        System.out.println("tricky()=" + tricky());
        System.out.println("withValue()=" + withValue());
    }
}
